import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.7R1OEGYz.js";const c=JSON.parse('{"title":"Continue a session locally","description":"","frontmatter":{},"headers":[],"relativePath":"local-sessions.md","filePath":"local-sessions.md","lastUpdated":1792248885000}'),n={name:"local-sessions.md"};function l(h,s,o,r,d,p){return i(),t("div",null,[...s[0]||(s[0]=[a('<h1 id="continue-a-session-locally" tabindex="-1">Continue a session locally <a class="header-anchor" href="#continue-a-session-locally" aria-label="Permalink to &quot;Continue a session locally&quot;">​</a></h1><p>Take an existing conversation from AgentHub to a matching local checkout. The transfer copies conversation history; it does <strong>not</strong> copy the repository, uncommitted project files, or session attachments. Check out the project locally first and download attachments separately.</p><table tabindex="0"><thead><tr><th>Agent</th><th>Continue locally</th><th>Return the local conversation to AgentHub</th></tr></thead><tbody><tr><td>Claude Code</td><td>Plugin: <code>pull</code>, then <code>claude --resume</code></td><td>Plugin: <code>push</code>, with the hub session paused</td></tr><tr><td>Codex</td><td>Skill: <code>pull</code>, then <code>codex resume</code></td><td>Not implemented</td></tr><tr><td>Other agents</td><td>No helper described here</td><td>No helper described here</td></tr></tbody></table><p>The helpers live in the <a href="https://github.com/open-agenthub/plugins" target="_blank" rel="noreferrer">plugins repository</a>, separately from the AgentHub release. Both read <code>AGENTHUB_URL</code> and <code>AGENTHUB_TOKEN</code>, or <code>~/.agenthub/cli.json</code>. Create a personal token in <strong>Settings → API tokens</strong>; its value starts with <code>oah_</code>. Configure it locally and keep it out of chat messages and screenshots. An <a href="/docs/mcp">MCP connection</a> does not automatically configure these download helpers.</p><h2 id="claude-code-install-the-plugin" tabindex="-1">Claude Code: install the plugin <a class="header-anchor" href="#claude-code-install-the-plugin" aria-label="Permalink to &quot;Claude Code: install the plugin&quot;">​</a></h2><p>Requires Node on your workstation and a local Claude Code installation. Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-agenthub/plugins</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-sessions@open-agenthub</span></span></code></pre></div><p>The plugin provides the <strong>session-transfer</strong> skill. Ask Claude Code to continue an AgentHub session locally, giving the hub session ID and the matching local project directory. The plugin version verified for this guide is <strong>0.1.1</strong> (MIT).</p><h3 id="configure-and-choose-a-session" tabindex="-1">Configure and choose a session <a class="header-anchor" href="#configure-and-choose-a-session" aria-label="Permalink to &quot;Configure and choose a session&quot;">​</a></h3><p>The following commands run in the plugin context, where <code>CLAUDE_PLUGIN_ROOT</code> points to <code>plugins/agenthub-sessions</code>. For manual use, replace that variable with the installed plugin&#39;s absolute path.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_PLUGIN_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/scripts/agenthub-session.mjs&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">personal-api-toke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_PLUGIN_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/scripts/agenthub-session.mjs&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><h3 id="pull-and-continue" tabindex="-1">Pull and continue <a class="header-anchor" href="#pull-and-continue" aria-label="Permalink to &quot;Pull and continue&quot;">​</a></h3><p>Pause the hub session before continuing locally so two agents do not work on the same conversation. From your matching local checkout, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_PLUGIN_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/scripts/agenthub-session.mjs&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hub-session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The helper rewrites the transcript&#39;s working-directory metadata for this checkout and prints a <code>claude --resume &lt;id&gt;</code> command. Run that command in a new local Claude Code session from the same directory. Use <code>--dir &lt;path&gt;</code> to choose another checkout explicitly. Existing local transcripts with different content are protected from overwriting.</p><h3 id="return-to-agenthub" tabindex="-1">Return to AgentHub <a class="header-anchor" href="#return-to-agenthub" aria-label="Permalink to &quot;Return to AgentHub&quot;">​</a></h3><p>Keep the hub session paused, finish your local work, then run from the same checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_PLUGIN_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/scripts/agenthub-session.mjs&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_PLUGIN_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/scripts/agenthub-session.mjs&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hub-session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Verify that the local transcript belongs to the hub session you intend to replace. Push replaces the stored conversation while retaining the rest of the archived agent home. Resume the session in AgentHub afterwards. Uploads to a Running or Pending session are rejected with HTTP 409: a live pod would overwrite the upload when it next persists state. Repository changes must be transferred separately, for example through your normal Git workflow.</p><h2 id="codex-install-and-use-the-skill" tabindex="-1">Codex: install and use the skill <a class="header-anchor" href="#codex-install-and-use-the-skill" aria-label="Permalink to &quot;Codex: install and use the skill&quot;">​</a></h2><p>Copy <code>codex/skills/agenthub-session-transfer</code> from the <a href="https://github.com/open-agenthub/plugins/tree/main/codex/skills/agenthub-session-transfer" target="_blank" rel="noreferrer">plugins repository</a> into your local Codex skills directory. The helper requires <strong>Node 20+</strong> and local Codex. Ask Codex to use <strong>agenthub-session-transfer</strong>, providing the hub session ID or URL and local checkout. If using the helper manually, replace <code>&lt;skill-dir&gt;</code> below with the installed skill&#39;s absolute path. Configure the hub URL and personal token locally first.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/agenthub-codex.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/agenthub-codex.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hub-session-id-or-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/agenthub-codex.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hub-session-id-or-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">local-checkou</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>The helper imports one Codex rollout, assigns a fresh local thread UUID, and rewrites its working-directory metadata. Run the returned <code>codex resume &lt;local-thread-id&gt;</code> command from your chosen checkout in a new Codex conversation. The hub ID and local UUID are different. If needed, select a rollout explicitly with <code>--session &lt;rollout-uuid&gt;</code>.</p><p>This is an import only: it does not pause or change the hub session and provides no push command. A running session can be copied from its latest stored snapshot, which may omit newer turns. It does not restore pod authentication, configuration, hooks, MCP servers, or skills. Desktop sidebar discovery may require opening the imported thread through Codex first.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message or symptom</th><th>Next step</th></tr></thead><tbody><tr><td>Not configured</td><td>Set the hub URL and personal API token locally.</td></tr><tr><td>HTTP 401</td><td>Check whether the personal token is valid and has not been revoked.</td></tr><tr><td>No stored state</td><td>The session needs an archived run; a never-started session has nothing to transfer.</td></tr><tr><td>No compatible transcript</td><td>Use the helper matching the session&#39;s agent.</td></tr><tr><td>Several transcripts</td><td>Inspect the choices and pass <code>--session &lt;id&gt;</code>.</td></tr><tr><td>Claude cannot determine the remote directory</td><td>Pass <code>--remote-cwd &lt;path&gt;</code> with the pod&#39;s working directory.</td></tr><tr><td>Push returns HTTP 409</td><td>Pause the hub session and wait for it to stop before retrying.</td></tr></tbody></table><p>See the <a href="https://github.com/open-agenthub/plugins/blob/main/plugins/agenthub-sessions/skills/session-transfer/SKILL.md" target="_blank" rel="noreferrer">Claude skill</a>, <a href="https://github.com/open-agenthub/plugins/blob/main/codex/skills/agenthub-session-transfer/SKILL.md" target="_blank" rel="noreferrer">Codex skill</a>, and <a href="https://github.com/open-agenthub/open-agenthub/blob/main/docs/session-transfer.md" target="_blank" rel="noreferrer">archive API design</a> for implementation details.</p>',27)])])}const g=e(n,[["render",l]]);export{c as __pageData,g as default};
